// Relatório do dia (horário de Brasília). Somas de dinheiro são exatas: os decimais
// chegam em texto e são somados com BigInt, nunca com ponto flutuante.
const LIMITE_DECISOES = 200;
const DESLOCAMENTO_BRASILIA = '-03:00'; // sem horário de verão desde 2019

const agora = Date.now();
const escaparHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const DECIMAL = /^(-?)(\d+)(?:\.(\d+))?$/;

const somarDecimais = (textos) => {
  const validos = textos.filter((t) => typeof t === 'string' && DECIMAL.test(t));
  const casas = Math.max(0, ...validos.map((t) => (DECIMAL.exec(t)[3] || '').length));
  let total = 0n;
  for (const t of validos) {
    const [, sinal, inteiro, fracao = ''] = DECIMAL.exec(t);
    total += BigInt(`${sinal}${inteiro}${fracao.padEnd(casas, '0')}`);
  }
  const negativo = total < 0n;
  const digitos = (negativo ? -total : total).toString().padStart(casas + 1, '0');
  const inteiro = digitos.slice(0, digitos.length - casas);
  const fracao = casas > 0 ? `.${digitos.slice(digitos.length - casas)}` : '';
  return `${negativo ? '-' : ''}${inteiro}${fracao}`;
};

// Exibição apenas (como formatarDolar de @zentrade/dominio): a conta já foi feita em decimal.
const moeda = new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const moedaFina = new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 4 });
const usd = (t, formato = moeda) =>
  typeof t === 'string' && DECIMAL.test(t) ? `US$ ${formato.format(Number(t))}` : 'indisponível';

const dia = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(new Date(agora));
const inicioDoDia = Date.parse(`${dia}T00:00:00${DESLOCAMENTO_BRASILIA}`);

const erroDe = (itens) => {
  const comErro = itens.find((i) => i.json && i.json.error);
  return comErro ? String(comErro.json.error.message || comErro.json.error) : null;
};

const resumoItens = $('Buscar resumo').all();
const resumo = resumoItens[0] ? resumoItens[0].json : {};
const decisoesItens = $('Buscar decisões').all();
const decisoes = decisoesItens.map((i) => i.json).filter((d) => d && typeof d.id === 'string');
const ordensItens = $input.all();
const ordens = ordensItens.map((i) => i.json).filter((o) => o && typeof o.id === 'string');

const deHoje = decisoes.filter((d) => Number(d.em) >= inicioDoDia);
const porEstado = {};
const barreiras = {};
for (const d of deHoje) {
  porEstado[d.estado] = (porEstado[d.estado] || 0) + 1;
  for (const b of (d.risco && d.risco.barreiras) || []) barreiras[b.codigo] = (barreiras[b.codigo] || 0) + 1;
}

const taxasHoje = somarDecimais(
  ordens.flatMap((o) => (o.execucoes || []).filter((e) => Number(e.em) >= inicioDoDia).map((e) => e.taxaCotacao)),
);

const NOMES = {
  registrada: 'só registradas (observar)',
  barrada: 'barradas pelo risco',
  aguardando_aprovacao: 'aguardando aprovação',
  aprovada: 'aprovadas',
  recusada: 'recusadas',
  expirada: 'expiradas',
  executada: 'executadas',
  falhou: 'com falha',
};

const linhas = [`ZenTrade — relatório de ${dia.split('-').reverse().join('/')}`, ''];
const erroResumo = erroDe(resumoItens);
if (erroResumo) {
  linhas.push(`Não consegui buscar o resumo: ${erroResumo}`);
} else {
  linhas.push(`Resultado do dia: ${usd(resumo.resultadoHoje)}`);
  linhas.push(`Exposição agora: ${usd(resumo.exposicao)}`);
  linhas.push(`Maior queda em 30 dias: ${usd(resumo.maiorQueda30d)}`);
  linhas.push(`Custo de IA hoje: ${usd(resumo.custoIaHoje, moedaFina)}`);
  linhas.push(`Robôs ativos: ${resumo.robosAtivos ?? 'indisponível'}`);
  if (resumo.paradaTotal) linhas.push('Atenção: a parada total está LIGADA.');
}
linhas.push(`Taxas pagas hoje: ${erroDe(ordensItens) ? 'indisponível' : usd(taxasHoje)}`);
linhas.push('');

const erroDecisoes = erroDe(decisoesItens);
if (erroDecisoes) {
  linhas.push(`Não consegui buscar as decisões: ${erroDecisoes}`);
} else if (deHoje.length === 0) {
  linhas.push('Nenhuma decisão hoje.');
} else {
  const parcial = decisoes.length >= LIMITE_DECISOES ? ` (das ${LIMITE_DECISOES} mais recentes)` : '';
  linhas.push(`Decisões hoje: ${deHoje.length}${parcial}`);
  for (const [estado, total] of Object.entries(porEstado).sort((a, b) => b[1] - a[1])) {
    linhas.push(`• ${NOMES[estado] || estado}: ${total}`);
  }
  const top = Object.entries(barreiras).sort((a, b) => b[1] - a[1]).slice(0, 3);
  if (top.length > 0) linhas.push(`Barreiras mais comuns: ${top.map(([c, n]) => `${c} (${n})`).join(', ')}`);
}

return [{ json: { texto: escaparHtml(linhas.join('\n')), taxasHoje, decisoesHoje: deHoje.length } }];
